// Domain enums and record shapes. Pure + shared between server code and
// client components (formerly generated by Prisma). Column-level constraints
// live in migrations/0001_init.sql.

export type Role = 'INVESTOR' | 'TEAM';
export type InvestorType = 'INDIVIDUAL' | 'ENTITY';
export type InvestorState = 'PENDING' | 'AWAITING' | 'ACTIVE' | 'DECLINED';
export type NoteStatus = 'AWAITING' | 'ACTIVE' | 'MATURED' | 'REDEEMED';
export type DocumentKind = 'STATEMENT' | 'SUMMARY' | 'TAX' | 'AGREEMENT';

export interface User {
  id: string;
  role: Role;
  name: string;
  email: string;
  passwordHash: string;
  phone: string | null;
  failedLoginAttempts: number;
  lockedUntil: Date | null;
  mustChangePassword: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface Investor {
  id: string;
  legalName: string;
  type: InvestorType;
  email: string;
  phone: string | null;
  state: InvestorState;
  userId: string | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface Distribution {
  id: string;
  noteId: string;
  index: number;
  dueDate: Date;
  amountCents: number;
  paidDate: Date | null;
  reference: string | null;
}

export interface Note {
  id: string;
  investorId: string;
  principalCents: number;
  rateBps: number;
  termMonths: number;
  monthlyAmountCents: number;
  wireDate: Date | null;
  firstDistributionDate: Date | null;
  maturityDate: Date | null;
  distributionDay: number;
  status: NoteStatus;
  createdAt: Date;
  updatedAt: Date;
}

export interface BankingDetail {
  investorId: string;
  bankName: string;
  last4: string;
  method: string;
}

export interface NotifPref {
  investorId: string;
  distributionPosted: boolean;
  maturityReminder: boolean;
}

export interface Document {
  id: string;
  investorId: string;
  name: string;
  kind: DocumentKind;
  issuedDate: Date;
  storageKey: string;
}
